insert into public.recipe_catalog(id, payload) values ('sample-01', '{"id":"sample-01","name":"Gà kho gừng","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":30,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"chicken","amount":300.0,"unit":"g"},{"ingredientId":"ginger","amount":20.0,"unit":"g"},{"ingredientId":"fishsauce","amount":10.0,"unit":"ml"},{"ingredientId":"sugar","amount":5.0,"unit":"g"}],"steps":["Thái gà thành miếng vừa ăn, gừng thái sợi. Ướp gà với nước mắm và đường trong 10 phút.","Làm nóng nồi, đảo gà và gừng cho săn. Thêm nước xâm xấp.","Kho lửa nhỏ đến khi gà chín hoàn toàn và nước sánh. Nếm lại trước khi dùng."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-02', '{"id":"sample-02","name":"Trứng sốt cà chua","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":15,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"egg","amount":3.0,"unit":"quả"},{"ingredientId":"tomato","amount":200.0,"unit":"g"},{"ingredientId":"oil","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Rửa và thái cà chua. Đánh tan trứng với muối.","Đun nóng một nửa dầu, đảo trứng đến khi vừa đông rồi lấy ra.","Cho dầu còn lại vào chảo, xào mềm cà chua, thêm trứng và đảo đến khi chín."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-03', '{"id":"sample-03","name":"Đậu phụ sốt nấm","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":20,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"tofu","amount":300.0,"unit":"g"},{"ingredientId":"mushroom","amount":150.0,"unit":"g"},{"ingredientId":"soysauce","amount":15.0,"unit":"ml"},{"ingredientId":"oil","amount":8.0,"unit":"g"}],"steps":["Cắt đậu thành khối, làm sạch và thái nấm.","Làm nóng dầu, xào nấm rồi thêm nước tương và một ít nước.","Thả đậu vào, đun nhẹ khoảng 8 phút để ngấm sốt."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-04', '{"id":"sample-04","name":"Canh bí đỏ thịt băm","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món canh","image":null,"minutes":25,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"pumpkin","amount":300.0,"unit":"g"},{"ingredientId":"pork","amount":100.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Gọt bí, bỏ hạt và cắt khối. Băm nhỏ thịt.","Đun nước, cho thịt vào và khuấy tơi, hớt bọt.","Thêm bí, nấu đến khi mềm và thịt chín. Nêm muối."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-05', '{"id":"sample-05","name":"Bắp cải xào tỏi","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món rau","image":null,"minutes":15,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"cabbage","amount":300.0,"unit":"g"},{"ingredientId":"garlic","amount":8.0,"unit":"g"},{"ingredientId":"oil","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Rửa sạch, thái bắp cải. Băm tỏi.","Phi thơm tỏi với dầu, cho bắp cải vào đảo ở lửa vừa.","Nêm muối và xào đến độ mềm mong muốn."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-06', '{"id":"sample-06","name":"Cá hấp gừng","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":30,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"fish","amount":350.0,"unit":"g"},{"ingredientId":"ginger","amount":20.0,"unit":"g"},{"ingredientId":"onion","amount":100.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Làm sạch cá, ướp muối. Thái gừng và hành.","Xếp hành, cá và gừng lên đĩa chịu nhiệt.","Hấp đến khi thịt cá chín hoàn toàn, dễ tách bằng nĩa."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-07', '{"id":"sample-07","name":"Tôm xào rau củ","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":20,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"shrimp","amount":250.0,"unit":"g"},{"ingredientId":"carrot","amount":100.0,"unit":"g"},{"ingredientId":"cabbage","amount":150.0,"unit":"g"},{"ingredientId":"oil","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Rửa tôm đã bóc vỏ, thái nhỏ rau củ.","Xào cà rốt với dầu, thêm chút nước cho mềm.","Thêm tôm và bắp cải, đảo đến khi tôm chín và rau mềm. Nêm muối."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-08', '{"id":"sample-08","name":"Canh cà chua trứng","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món canh","image":null,"minutes":15,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"tomato","amount":200.0,"unit":"g"},{"ingredientId":"egg","amount":2.0,"unit":"quả"},{"ingredientId":"oil","amount":5.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Thái cà chua, đánh tan trứng.","Xào cà chua với dầu, thêm 600 ml nước và đun sôi.","Rót trứng từ từ, khuấy nhẹ, nấu trứng chín rồi nêm muối."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-09', '{"id":"sample-09","name":"Bò xào hành tây","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":20,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"beef","amount":250.0,"unit":"g"},{"ingredientId":"onion","amount":200.0,"unit":"g"},{"ingredientId":"garlic","amount":8.0,"unit":"g"},{"ingredientId":"oil","amount":10.0,"unit":"g"},{"ingredientId":"soysauce","amount":10.0,"unit":"ml"}],"steps":["Thái mỏng thịt bò và hành tây. Băm tỏi.","Phi tỏi với dầu, cho bò vào đảo nhanh.","Thêm hành và nước tương, xào đến khi thịt chín."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-10', '{"id":"sample-10","name":"Salad dưa leo cà chua","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món rau","image":null,"minutes":10,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"cucumber","amount":200.0,"unit":"g"},{"ingredientId":"tomato","amount":200.0,"unit":"g"},{"ingredientId":"oil","amount":5.0,"unit":"g"},{"ingredientId":"salt","amount":1.0,"unit":"g"}],"steps":["Rửa sạch rau, để ráo.","Thái dưa leo và cà chua vừa ăn.","Trộn nhẹ với dầu và muối ngay trước khi dùng."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-11', '{"id":"sample-11","name":"Cháo gà","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Ăn sáng","image":null,"minutes":45,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"rice","amount":100.0,"unit":"g"},{"ingredientId":"chicken","amount":200.0,"unit":"g"},{"ingredientId":"ginger","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Vo gạo. Luộc gà với gừng đến khi chín, lấy ra xé sợi.","Nấu gạo trong nước luộc gà, khuấy định kỳ đến khi nhừ.","Cho gà trở lại nồi, nêm muối và đun nóng."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-12', '{"id":"sample-12","name":"Canh rau chân vịt","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món canh","image":null,"minutes":15,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"spinach","amount":250.0,"unit":"g"},{"ingredientId":"tofu","amount":150.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Rửa rau, cắt đậu thành khối.","Đun sôi 600 ml nước, cho đậu vào nấu nhẹ.","Thêm rau, nấu chín và nêm muối."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-13', '{"id":"sample-13","name":"Khoai tây xào thịt","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":25,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"potato","amount":250.0,"unit":"g"},{"ingredientId":"pork","amount":150.0,"unit":"g"},{"ingredientId":"onion","amount":100.0,"unit":"g"},{"ingredientId":"oil","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Thái mỏng khoai, thịt và hành tây.","Xào thịt với dầu đến khi săn, thêm khoai cùng một ít nước.","Đậy nắp cho khoai mềm, thêm hành và nấu đến khi thịt chín hoàn toàn."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-14', '{"id":"sample-14","name":"Trứng cuộn rau củ","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":20,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"egg","amount":3.0,"unit":"quả"},{"ingredientId":"carrot","amount":50.0,"unit":"g"},{"ingredientId":"onion","amount":50.0,"unit":"g"},{"ingredientId":"oil","amount":8.0,"unit":"g"},{"ingredientId":"salt","amount":1.0,"unit":"g"}],"steps":["Băm nhỏ rau củ và trộn với trứng, muối.","Làm nóng dầu, tráng một lớp trứng mỏng.","Cuộn dần và thêm trứng còn lại, nấu chín rồi cắt khoanh."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-15', '{"id":"sample-15","name":"Đậu phụ kho cà chua","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":25,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"tofu","amount":300.0,"unit":"g"},{"ingredientId":"tomato","amount":250.0,"unit":"g"},{"ingredientId":"oil","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Cắt đậu, thái cà chua.","Áp chảo đậu với dầu rồi lấy ra. Xào mềm cà chua.","Cho đậu trở lại, thêm nước và muối, kho nhỏ lửa 10 phút."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-16', '{"id":"sample-16","name":"Cơm gà rau củ","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món chính","image":null,"minutes":40,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"rice","amount":150.0,"unit":"g"},{"ingredientId":"chicken","amount":250.0,"unit":"g"},{"ingredientId":"carrot","amount":100.0,"unit":"g"},{"ingredientId":"cucumber","amount":100.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Vo gạo và nấu cơm theo lượng nước phù hợp.","Luộc gà và cà rốt đến khi chín; thái dưa leo.","Xếp cơm, gà và rau ra đĩa, nêm theo khẩu vị."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-17', '{"id":"sample-17","name":"Nấm xào tỏi","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món rau","image":null,"minutes":15,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"mushroom","amount":300.0,"unit":"g"},{"ingredientId":"garlic","amount":10.0,"unit":"g"},{"ingredientId":"oil","amount":8.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Làm sạch nấm, để ráo và thái miếng. Băm tỏi.","Làm nóng dầu, phi tỏi rồi cho nấm vào.","Xào chín nấm và nêm muối."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-18', '{"id":"sample-18","name":"Canh khoai tây cà rốt","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món canh","image":null,"minutes":30,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"potato","amount":200.0,"unit":"g"},{"ingredientId":"carrot","amount":150.0,"unit":"g"},{"ingredientId":"mushroom","amount":100.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Gọt và cắt khoai, cà rốt; làm sạch nấm.","Đun nước, cho khoai và cà rốt vào nấu mềm.","Thêm nấm, nấu chín và nêm muối."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-19', '{"id":"sample-19","name":"Bún gà","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Ăn sáng","image":null,"minutes":35,"servings":2,"vegetarian":false,"favorite":false,"sample":true,"items":[{"ingredientId":"noodle","amount":300.0,"unit":"g"},{"ingredientId":"chicken","amount":250.0,"unit":"g"},{"ingredientId":"onion","amount":100.0,"unit":"g"},{"ingredientId":"ginger","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Luộc gà với gừng và hành đến khi gà chín hoàn toàn.","Lấy gà ra xé sợi, nêm nước dùng.","Làm nóng bún, xếp gà lên và chan nước dùng nóng."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
insert into public.recipe_catalog(id, payload) values ('sample-20', '{"id":"sample-20","name":"Bí đỏ xào tỏi","description":"Công thức gia đình cho 2 người. Điều chỉnh gia vị theo khẩu vị.","category":"Món rau","image":null,"minutes":20,"servings":2,"vegetarian":true,"favorite":false,"sample":true,"items":[{"ingredientId":"pumpkin","amount":300.0,"unit":"g"},{"ingredientId":"garlic","amount":8.0,"unit":"g"},{"ingredientId":"oil","amount":10.0,"unit":"g"},{"ingredientId":"salt","amount":2.0,"unit":"g"}],"steps":["Gọt bí, bỏ hạt và thái lát mỏng. Băm tỏi.","Phi tỏi với dầu, thêm bí và đảo đều.","Thêm chút nước, đậy nắp cho bí mềm rồi nêm muối."]}'::jsonb) on conflict(id) do update set payload = excluded.payload;
